arguments.cmd:
cd /tmp && rm -rf flexonly && mkdir flexonly && cd flexonly && cat > model.scad <<'EOF'
part = "assembly";
cadverify_only = "";
module instance(name, part, unit = 1) {
    echo(cadverify_instance = [name, part, unit]);
    if (cadverify_only == "" || cadverify_only == name) children();
}
module leaf() {
    cube([30, 25, 3]);
    translate([15, 6.1, 2.5]) rotate([-40.85, 0, 0])
        translate([-2.52, -0.84, 0]) cube([5.04, 1.68, 11.77]);
    translate([15 - 2.52, 6.4, 3.0]) rotate([0, 90, 0])
        cylinder(r = 1.5, h = 5.04, $fn = 24);
    translate([15 - 2.52, 14.1, 9.4]) cube([5.04, 4.5, 1.5]);
    translate([15, 18.6, 9.4]) cylinder(r = 0.65, h = 1.5, $fn = 24);
}
module block() {
    translate([12.4, 16.6, 8.0]) cube([5.2, 4.0, 4.0]);
}
if (part == "leaf") {
    echo(cadverify_spec = [
        ["bounds", [[0, 0, 0], [30, 25, 10.9]]],
        ["bodies", 1], ["through_holes", 0],
        ["support_faces", [["bed", "-z", 500]]],
        ["overhangs_allowed", [["u", [[12, 3.5, 2.0], [18, 21.2, 10.5]]]]],
        ["copies", 1], ["material", "PLA"],
        ["details", []]]);
    leaf();
} else if (part == "block") {
    echo(cadverify_spec = [
        ["bounds", [[12.4, 16.6, 8.0], [17.6, 20.6, 12.0]]],
        ["bodies", 1], ["through_holes", 0],
        ["support_faces", [["bed", "-z", 10]]],
        ["overhangs_allowed", []],
        ["copies", 1], ["material", "PLA"],
        ["details", []]]);
    block();
} else if (part == "assembly") {
    echo(cadverify_spec = [
        ["bounds", [[0, 0, 0], [30, 25, 12.0]]],
        ["allowed_interferences", []],
        ["motions", [["m", ["leaf"], "slide", [0, -1, 0], [0, 0.5],
            ["flex", [["leaf", "block", 0.5, "test", [2, 10]]]]]],
        ["assembly_order", [[["leaf", "block"], [0, 0, 0]]]],
        ["material", "PLA"]]);
    instance("leaf", "leaf") leaf();
    instance("block", "block") block();
}
EOF
timeout 200 cadcheck behaviour --out-dir /tmp/flexonly/out model.scad 2>&1 | tail -40
